"use client";
/* Fluff, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Fluff(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("fluff"); }, []);
  return React.createElement("piix-sprite", { "name": "fluff", ...piixAttrs(props) });
}

export default Fluff;
